示意代码：
```cpp
template <typename T>
void processHelper(const T& t, std::true_type) {
    std::cout << t << " is integral type." << std::endl;
}

template <typename T>
void processHelper(const T& t, std::false_type) {
    std::cout << t << " is a non-integral type." << std::endl;
}

template <typename T>
void process(const T& t) {
    processHelper(t, typename std::is_integral<T>::type{});
}
```
